"""Request handling for the API."""

from collections.abc import Mapping
from typing import Any


def _validate_request(data: object, request_id: object) -> None:
    """Validate request metadata and payload before any side effects occur.

    API request bodies must be JSON-object-like mappings, and request IDs must
    be non-empty strings.  Keeping these checks in one place ensures invalid
    requests are neither written to the audit log nor passed to the processor.
    """
    if not isinstance(request_id, str):
        raise TypeError("request_id must be a string")
    if not request_id.strip():
        raise ValueError("request_id must not be empty")

    if not isinstance(data, Mapping):
        raise TypeError("data must be a mapping")
    if any(not isinstance(key, str) for key in data):
        raise ValueError("data keys must be strings")


def handle_request(data: Mapping[str, Any], request_id: str) -> Any:
    """Validate, audit, and process an incoming API request."""
    _validate_request(data, request_id)
    audit_log(request_id, data)
    return process(data)

